import{_ as t,o as a,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Orchestrator Meeting 2023-03-21","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2023-03-21","date":"2023-03-21T00:00:00.000Z","updated":"2023-03-22T00:00:00.000Z","tags":["Ceph","分布式存储","迁移计划","技术讨论","超时处理"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Orchestrator_Meeting_2023-03-21.md","filePath":"posts/2023/Ceph_Orchestrator_Meeting_2023-03-21.md","lastUpdated":1780459816000}'),i={name:"posts/2023/Ceph_Orchestrator_Meeting_2023-03-21.md"};function o(s,e,n,h,d,g){return a(),l("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-视频会议平台迁移与技术讨论" tabindex="-1">会议主题：视频会议平台迁移与技术讨论 <a class="header-anchor" href="#会议主题-视频会议平台迁移与技术讨论" aria-label="Permalink to &quot;会议主题：视频会议平台迁移与技术讨论&quot;">​</a></h4><h4 id="会议时间-2023年3月21日" tabindex="-1">会议时间：2023年3月21日 <a class="header-anchor" href="#会议时间-2023年3月21日" aria-label="Permalink to &quot;会议时间：2023年3月21日&quot;">​</a></h4><h4 id="参会人员-参会人员名单" tabindex="-1">参会人员：[参会人员名单] <a class="header-anchor" href="#参会人员-参会人员名单" aria-label="Permalink to &quot;参会人员：[参会人员名单]&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>视频会议平台迁移计划</strong></p><ul><li><strong>当前问题</strong>：Blue Jeans视频会议平台将于4月1日关闭，需寻找替代方案。</li><li><strong>讨论内容</strong>：在CLT会议中讨论了Google Meet和Jitsi作为替代方案，由于Google Meet存在权限问题和需要Google账户，倾向于使用Jitsi。</li><li><strong>决定事项</strong>：计划迁移到已有的Jitsi会议室，但需要解决录音问题，目前录音需手动触发，不同于Blue Jeans的自动录音。</li><li><strong>后续行动</strong>：预计会有几周时间没有录音，直到问题解决。下周将继续使用Blue Jeans，之后迁移到Jitsi。</li></ul></li><li><p><strong>技术讨论：通用超时处理</strong></p><ul><li><strong>问题背景</strong>：存在多个可能导致命令超时的问题，如卷进程达到极限点、节点根文件系统无空间等。</li><li><strong>讨论内容</strong>：提出了三种解决方案： <ol><li>在fdm二进制文件中添加超时标志。</li><li>使用线程系统，启动单独线程并设置超时。</li><li>使用异步IO，通过内部函数传递超时。</li></ol></li><li><strong>决定事项</strong>：倾向于使用异步IO方案，因其实现简单且异常处理更方便。</li><li><strong>后续行动</strong>：将删除测试用例中的临时代码，编写更正式的单元测试和集成测试。</li></ul></li></ol><h4 id="其他讨论" tabindex="-1">其他讨论： <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论：&quot;">​</a></h4><ul><li>对于视频会议平台的迁移，提醒参会人员注意个人日历的更新，确保不会错过会议。</li><li>对于技术讨论，鼓励进一步的测试和实施细节的完善。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>感谢所有参会人员的参与，下周将继续使用Blue Jeans，之后迁移到Jitsi。</li><li>提醒参会人员注意日历更新，确保顺利过渡到新的会议平台。</li></ul><h4 id="下次会议预告" tabindex="-1">下次会议预告： <a class="header-anchor" href="#下次会议预告" aria-label="Permalink to &quot;下次会议预告：&quot;">​</a></h4><ul><li>下周会议将继续使用Blue Jeans平台。</li><li>之后将迁移到Jitsi平台，并解决录音问题。</li></ul><p><strong>会议结束时间：[具体时间]</strong></p><p><strong>记录人：[记录人姓名]</strong></p><p><strong>审核人：[审核人姓名]</strong></p>',15)])])}const p=t(i,[["render",o]]);export{c as __pageData,p as default};
